"""Generated auditor knowledge (REQ-AUD-16 AC3).

The knowledge document the model reads for pattern judgment is GENERATED from our structured
records — the known-defect log, and (when supplied) the VEX evidence sidecars — never
free-written by the model. Generation is DETERMINISTIC: the same records in produce byte-for-byte
the same document, with no model call. Only TRUSTED records contribute; a model-proposed row
(disposition == "proposed") is excluded until it is merged as a trusted entry.
"""
import json

_UNTRUSTED = ("proposed",)


def _note(d):
    """A short evidence note for a defect row, tolerant of a string OR dict evidence field."""
    ev = d.get("evidence")
    if isinstance(ev, dict):
        ev = ev.get("detail") or json.dumps(ev, sort_keys=True)
    return str(ev or d.get("affected_version_range") or "recorded").strip()


def generate(log, evidence=None):
    """Return the knowledge document (Markdown) generated from a known-defect log dict and an
    optional {statement_id: evidence} map from the VEX sidecars. Pure and deterministic."""
    defects = (log or {}).get("defects", []) or []
    trusted = [d for d in defects if d.get("disposition") and d.get("disposition") not in _UNTRUSTED]
    src = "the known-defect log" + (" and the VEX evidence sidecars" if evidence else "")
    L = ["# Auditor knowledge (generated — do not edit by hand)", "",
         "Generated by auditorlib.knowledge from %s. Every entry is backed by a recorded (scanner,"
         " finding, purl) key and its evidence; nothing here is free-written, and a model-proposed"
         " row does not appear until it is merged as a trusted entry." % src, ""]

    L += ["## Scanner-defect patterns", ""]
    if not trusted:
        L += ["None recorded yet.", ""]
    else:
        by_scanner = {}
        for d in trusted:
            for k in d.get("keys", []):
                by_scanner.setdefault(k.get("scanner") or "?", []).append((d, k))
        for sc in sorted(by_scanner):
            L.append("- **%s** has recorded dispositions on:" % sc)
            seen = set()
            for d, k in sorted(by_scanner[sc], key=lambda x: (x[1].get("finding_id") or "", x[0].get("package") or "")):
                dedup = (k.get("finding_id"), d.get("package"))
                if dedup in seen:
                    continue
                seen.add(dedup)
                L.append("  - `%s` on `%s` — %s: %s"
                         % (k.get("finding_id") or "?", d.get("package") or "?",
                            d.get("disposition"), _note(d)[:240]))
        L.append("")

    L += ["## Package-level notes", ""]
    if not trusted:
        L += ["None recorded yet.", ""]
    else:
        by_pkg = {}
        for d in trusted:
            by_pkg.setdefault(d.get("package") or "?", []).append(d)
        for pkg in sorted(by_pkg):
            cves = sorted({k.get("finding_id") for d in by_pkg[pkg] for k in d.get("keys", []) if k.get("finding_id")})
            dispositions = sorted({d.get("disposition") for d in by_pkg[pkg] if d.get("disposition")})
            L.append("- **%s** (%s): %s" % (pkg, ", ".join(dispositions), ", ".join(cves)))
        L.append("")
    return "\n".join(L) + "\n"
